INSERT INTO `tour_azerbaijan_activities_2026` (`id`, `name`, `service`, `description`, `open_time`, `close_time`, `duration_mins`, `slots`, `season`, `adult_price`, `child_price_6_12`, `valid_from`, `valid_to`, `sort_order`, `created_at`, `city`) VALUES
(1, 'Maiden Tower', 'Entry Ticket', 'The Maiden Tower, a 12th-century UNESCO-listed landmark in Baku’s Old City (Icherisheher), is known for its unique cylindrical shape and mysterious origins. It offers panoramic views of the city and is one of Baku’s most iconic symbols, surrounded by legends about its construction and purpose.\n\nNote: \n- Not recommended for people with claustrophobia or those with knee or heart problems. \n- Children must be closely supervised. \n- No elevators are available, and comfortable shoes are recommended.', NULL, NULL, NULL, NULL, '9', 9.00, NULL, NULL, NULL, 0, '2026-02-20 09:04:52', 'baku'),
(2, 'Shirvanshah Palace', 'Entry Ticket', '- The Shirvanshah’s Palace, built in the 15th century, served as the royal residence of the Shirvanshah dynasty and is considered one of Azerbaijan’s finest medieval architectural masterpieces. The complex includes a mosque, mausoleum, and ceremonial courtyard that reflect the cultural peak of the Shirvan state. \n\nNOTE: It stands as a UNESCO-listed symbol of Azerbaijan’s rich royal history.', NULL, NULL, NULL, NULL, '9', 9.00, NULL, NULL, NULL, 0, '2026-02-20 09:04:52', 'baku'),
(3, 'Miniature book museum', 'Entry Ticket', '- The museum opened on April 2, 2002. Some of the books are extremely small micro-books published in Tokyo measuring just 0.75 × 0.75 mm, or 2 × 2 mm — so tiny they can be read only with a magnifying glass. In 2015 it was officially recognized by Guinness World Records as the world’s largest private collection of miniature books.\n\nNOTE: Mondays and Thursdays are non-operational days.', NULL, NULL, NULL, NULL, '1', 1.00, NULL, NULL, NULL, 0, '2026-02-20 09:04:52', 'baku'),
(4, 'Gala Historical & Ethnographic Reserve', 'Entry Ticket', '- Established as a protected historical-ethnographic reserve in 1988, Gala Reserve offers a panoramic journey through human life on the Absheron Peninsula from ancient times to the Middle Ages.\n- Exhibits include archaeological monuments, reconstructed traditional houses and village life, cultural artifacts, historic structures, old ovens, workshops, and traditional crafts.', NULL, NULL, NULL, NULL, '9', 5.00, NULL, NULL, NULL, 0, '2026-02-20 09:04:52', 'baku'),
(5, 'Underground Historical Hamam ', 'Entry Ticket', '- The Underground Bath is a historic hamam on Boyuk Gala Street, near the fortress gates of Icherisheher, Baku, dating back to the early 17th century.', NULL, NULL, NULL, NULL, '10', 10.00, NULL, NULL, NULL, 0, '2026-02-20 09:04:52', 'baku'),
(6, 'Traditional Hamam', 'Entry Ticket: Male ', '- Traditional Hamam Experience: Includes steam and sauna, soaping and scrubbing by a male attendant, Turkish hamam rituals, hot & cold showers, towel, rubber slippers, and local tea.', NULL, NULL, NULL, NULL, '25', 25.00, NULL, NULL, NULL, 0, '2026-02-20 09:04:52', 'baku'),
(7, 'Traditional Hamam', 'Entry Ticket: Female ', '- Traditional Hamam Experience: Includes steam and sauna, soaping and scrubbing by a female attendant, Turkish hamam rituals, hot & cold showers, towel, rubber slippers, and local tea.', NULL, NULL, NULL, NULL, '22', 22.00, NULL, NULL, NULL, 0, '2026-02-20 09:04:52', 'baku'),
(8, 'Carpet museum', 'Entry Ticket', '- The Azerbaijan Carpet Museum, founded in 1967, houses the world’s largest collection of Azerbaijani carpets and weaving artifacts in its iconic rolled-carpet-shaped building.\n\nNOTE: It showcases centuries-old regional carpet traditions, recognized by UNESCO as Intangible Cultural Heritage.', NULL, NULL, NULL, NULL, '6', 6.00, NULL, NULL, NULL, 0, '2026-02-20 09:04:52', 'baku'),
(9, 'Gondola ride in Mini Venice', 'Entry Ticket: 1 Lap', '- The Mini Venice Gondola Ride is a charming single-lap journey through picturesque canals, offering scenic views of bridges, architecture, and lush surroundings inspired by Venice.\n\nNote: Each gondola accommodates a maximum of 4 people.\n', NULL, NULL, NULL, NULL, '3', 3.00, NULL, NULL, NULL, 0, '2026-02-20 09:04:52', 'baku'),
(11, 'Heydar Aliyev Center Museum', 'Entry Ticket', '- The Heydar Aliyev Center, designed by Zaha Hadid and opened in 2012, is an iconic landmark of modern Azerbaijani architecture showcasing the country’s cultural and artistic heritage.\n\nNote: The museum is closed on Mondays.', NULL, NULL, NULL, NULL, '9', 9.00, NULL, NULL, NULL, 0, '2026-02-20 09:04:52', 'baku'),
(12, 'Victory Museum ', 'Entry Ticket', '- The Victory Museum in Baku’s Victory Park commemorates Azerbaijan’s triumph in the 44-day Patriotic War, featuring a grand memorial complex.\n\nNOTE: it includes 8 exhibition halls detailing the Karabakh conflict, major operations, the liberation of Shusha, and the restoration of sovereignty.', NULL, NULL, NULL, NULL, '9', 4.00, NULL, NULL, NULL, 0, '2026-02-20 09:04:52', 'baku'),
(13, 'Vintage Car museum', 'Entry Ticket', '- The Vintage Car Museum, located inside the Heydar Aliyev Center designed by Zaha Hadid, showcases classic automobiles from the 20th century, including rare Soviet-era and European luxury cars.\n\nNote: The museum is closed on Mondays.', NULL, NULL, NULL, NULL, '6', 6.00, NULL, NULL, NULL, 0, '2026-02-20 09:04:52', 'baku'),
(14, 'Go Karting (Outdoor - FIT)', 'Entry Ticket : Time: 10 min', '- The outdoor track at Baku Karting Center caters to groups, combining racing with social interaction and team competition. Participants can race simultaneously, compete in friendly challenges, or enjoy a shared motorsport experience. A cafeteria is available on-site for guests to relax between turns.\n\nNote: The session lasts 10 minutes, covering 5 laps. Up to 6 people can participate in each lap at the same time. 1 hour can accommodate a group of 36 people.', NULL, NULL, NULL, NULL, '21', 21.00, NULL, NULL, NULL, 0, '2026-02-20 09:04:52', 'baku'),
(15, 'Go Karting (Outdoor - GIT)', 'Entry Ticket : Time: 10 min', '- The outdoor track at Baku Karting Center caters to groups, combining racing with social interaction and team competition. Participants can race simultaneously, compete in friendly challenges, or enjoy a shared motorsport experience. A cafeteria is available on-site for guests to relax between turns.\n\nNote: The session lasts 10 minutes, covering 5 laps. Up to 6 people can participate in each lap at the same time. 1 hour can accommodate a group of 36 people.', NULL, NULL, NULL, NULL, '21', 21.00, NULL, NULL, NULL, 0, '2026-02-20 09:04:52', 'baku'),
(16, 'Go Karting (Indoor - FIT)', 'Entry Ticket : Time: 10 min', 'Indoor karting at Deniz Mall is designed for groups, letting participants race together on a professionally designed circuit. The track encourages friendly competition, teamwork, and shared excitement in a controlled, safe environment.\n\nNote: The session lasts 10 minutes, covering 5 laps and up to 5 people can participate in each lap at the indoor track in at the same time. 1 hour can accommodate a group of 30 people.', NULL, NULL, NULL, NULL, '15', 15.00, NULL, NULL, NULL, 0, '2026-02-20 09:04:52', 'baku'),
(17, 'Go Karting (Indoor - GIT)', 'Entry Ticket : Time: 10 min', '- Indoor karting at Deniz Mall is designed for groups, letting participants race together on a professionally designed circuit. The track encourages friendly competition, teamwork, and shared excitement in a controlled, safe environment.\n\nNote: The session lasts 10 minutes, covering 5 laps and up to 5 people can participate in each lap at the indoor track in at the same time. 1 hour can accommodate a group of 30 people.', NULL, NULL, NULL, NULL, '11', 11.00, NULL, NULL, NULL, 0, '2026-02-20 09:04:52', 'baku'),
(18, 'Horse Riding', 'Entry Ticket : 1 ride 10 min', '- Horse riding in Baku provides a scenic and enjoyable outdoor activity suitable for individuals, families, and small groups. The activity combines the thrill of equestrian sport with the opportunity to enjoy nature and traditional horsemanship.\n\nNote: Each ride lasts 10 minutes. Begining-level training by instuctor & helmet is included.', NULL, NULL, NULL, NULL, '15', 15.00, NULL, NULL, NULL, 0, '2026-02-20 09:04:52', 'baku'),
(19, 'Paintball', 'Entry Ticket : 100 Bullets', '- Paintball in Baku offers an exciting outdoor activity where participants engage in strategic, team-based games on obstacle-filled fields, testing skill, teamwork, and tactics.\n\nNote: Equipment and helmet are provided, each participant gets 100 paintballs, teams of up to 8 players, and the activity is supervised by trained instructors for safety.\n', NULL, NULL, NULL, NULL, '12', 12.00, NULL, NULL, NULL, 0, '2026-02-20 09:04:52', 'baku'),
(20, 'Cruise Tour', 'Entry Ticket : 1 ride 20 min', '- Mirvari Boat Cruise along Baku Boulevard has a scenic tour of the Caspian Sea, letting visitors enjoy city skyline views, waterfront attractions, and the lively boulevard atmosphere.\n\nNote: Can accommodate 200 people per trip, duration 20–25 minutes, and operates weather permitting.', NULL, NULL, NULL, NULL, '3', 3.00, NULL, NULL, NULL, 0, '2026-02-20 09:04:52', 'baku'),
(21, 'Cruise Tour VIP', 'Entry Ticket : 1 ride 20 min ', '- Mirvari Boat Cruise along Baku Boulevard has a scenic tour of the Caspian Sea, letting visitors enjoy city skyline views, waterfront attractions, and the lively boulevard atmosphere.\n\nNote: Can accommodate 200 people per trip, duration 20–25 minutes, and operates weather permitting.', NULL, NULL, NULL, NULL, '6', 6.00, NULL, NULL, NULL, 0, '2026-02-20 09:04:52', 'baku'),
(22, 'Paintball', 'Entry Ticket : 100 Bullets', '- Paintball in Baku offers an exciting outdoor activity where participants engage in strategic, team-based games on obstacle-filled fields, testing skill, teamwork, and tactics.  Note: Equipment and helmet are provided, each participant gets 100 paintballs, teams of up to 8 players, and the activity is supervised by trained instructors for safety. ', NULL, NULL, NULL, NULL, '12', 12.00, NULL, NULL, NULL, 0, '2026-02-20 09:04:52', 'baku'),
(23, 'Bowling (Deniz Mall)', 'Entry Ticket : 1 hour play, including shoes', '- The facility combines casual entertainment with friendly competition, making it a popular choice for both leisure and group activities.\n\nNote: Bowling shoes are included. Each session includes 1 hour of play.', NULL, NULL, NULL, NULL, '25', 25.00, NULL, NULL, NULL, 0, '2026-02-20 09:04:52', 'baku'),
(31, 'Golf', 'Entry Ticket : 9 holes', NULL, NULL, NULL, NULL, NULL, '65', 65.00, NULL, NULL, NULL, 0, '2026-02-20 09:04:52', 'baku'),
(32, 'Golf', 'Entry Ticket : 18 holes', NULL, NULL, NULL, NULL, NULL, '112', 112.00, NULL, NULL, NULL, 0, '2026-02-20 09:04:52', 'baku'),
(33, 'Yacht tour', 'Entry Ticket : 1 hr (6 pax), Boat Type - Mini Kater', '- By sailing experience on the Caspian Sea guests can enjoy panoramic views of the city skyline, the Seaside Boulevard, and the surrounding coastal landscapes. The tour starts from the Seaside Boulevard, a national park, and sails all the way to the shores of Great Zira Island.\n\nNote: Catering food & drinking alcohol is allowed. Yacht can accommodates 6 people for a 1-hour trip. ', NULL, NULL, NULL, NULL, '30', 30.00, NULL, NULL, NULL, 0, '2026-02-20 09:04:52', 'baku'),
(34, 'Yacht tour', 'Entry Ticket : 2 hr (6 pax), Boat Type - Mini Kater', '- By sailing experience on the Caspian Sea guests can enjoy panoramic views of the city skyline, the Seaside Boulevard, and the surrounding coastal landscapes. The tour starts from the Seaside Boulevard, a national park, and sails all the way to the shores of Great Zira Island.\n\nNote: Catering food & drinking alcohol is allowed. Yacht can accommodates 6 people for 2-hours\' trip. ', NULL, NULL, NULL, NULL, '65', 65.00, NULL, NULL, NULL, 0, '2026-02-20 09:04:52', 'baku'),
